import Foundation
import ApplicationServices

func attr(_ element: AXUIElement, _ name: CFString) -> AnyObject? {
    var value: CFTypeRef?
    let err = AXUIElementCopyAttributeValue(element, name, &value)
    return err == .success ? value : nil
}

func children(of element: AXUIElement) -> [AXUIElement] {
    guard let value = attr(element, kAXChildrenAttribute) as? [AXUIElement] else { return [] }
    return value
}

func title(of element: AXUIElement) -> String? {
    for key in [kAXTitleAttribute, kAXDescriptionAttribute, kAXValueAttribute] as [CFString] {
        if let v = attr(element, key) as? String, !v.isEmpty { return v }
    }
    return nil
}

func role(of element: AXUIElement) -> String? {
    return attr(element, kAXRoleAttribute) as? String
}

func find(_ element: AXUIElement, match: (AXUIElement) -> Bool) -> AXUIElement? {
    if match(element) { return element }
    for child in children(of: element) {
        if let found = find(child, match: match) { return found }
    }
    return nil
}

let apps = AXUIElementCreateSystemWide()
let proc = NSWorkspace.shared.runningApplications.first { $0.bundleIdentifier == "com.apple.iphonesimulator" }
let pid = proc?.processIdentifier ?? 0
if pid == 0 {
    fputs("Simulator not found\n", stderr)
    exit(1)
}
let app = AXUIElementCreateApplication(pid)
var focusedWindow: AnyObject?
AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &focusedWindow)
let root = (focusedWindow as? AXUIElement) ?? app

let target = find(root) { e in
    guard let t = title(of: e)?.lowercased() else { return false }
    return t == "feeds" || t.contains("feeds")
}

if let target = target {
    let ok = AXUIElementPerformAction(target, kAXPressAction as CFString)
    print(ok == .success ? "pressed" : "press_failed:\(ok.rawValue)")
} else {
    print("not_found")
}
